{
  "root": "main_stack",
  "state": {
    "roadmap_rows": [
      {
        "month_phase": "Month 1: Foundation & Planning",
        "goal": "Establish event structure; Secure initial resources.",
        "key_tasks": "Define event type, date, and venue; Set fundraising goal & budget; Form core organizing committee; Create event brand & messaging; Research potential sponsors; Draft volunteer roles & recruitment plan.",
        "deliverable": "Event concept document; Budget draft; Core team assigned; Initial sponsor list; Volunteer plan."
      },
      {
        "month_phase": "Month 2: Outreach & Mobilization",
        "goal": "Drive fundraising efforts; Recruit and train volunteers; Promote event.",
        "key_tasks": "Launch fundraising campaigns (online, local businesses); Recruit & onboard volunteers; Develop marketing materials (flyers, social media); Secure event permits & insurance; Finalize vendor contracts; Plan event logistics (setup, catering, activities).",
        "deliverable": "Fundraising targets met (e.g., 50%); Volunteer roster (e.g., 80% filled); Marketing campaign live; Permits secured; Vendor agreements."
      },
      {
        "month_phase": "Month 3: Execution & Follow-up",
        "goal": "Successfully host the event; Manage volunteers; Acknowledge support.",
        "key_tasks": "Execute event day schedule; Manage volunteer shifts & responsibilities; Oversee vendor operations; Handle on-site issues; Post-event cleanup; Send thank-you notes to sponsors, volunteers, and attendees; Conduct post-event survey; Financial reconciliation.",
        "deliverable": "Successful event execution; Post-event report; Financial summary; Stakeholder acknowledgments."
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_text",
        "roadmap_table"
      ]
    },
    "title_text": {
      "type": "Text",
      "props": {
        "text": "Event Planning Roadmap",
        "variant": "h2"
      },
      "children": []
    },
    "roadmap_table": {
      "type": "Table",
      "props": {
        "statePath": "/roadmap_rows",
        "columns": [
          {
            "key": "month_phase",
            "label": "Month/Phase"
          },
          {
            "key": "goal",
            "label": "Goal"
          },
          {
            "key": "key_tasks",
            "label": "Key Tasks"
          },
          {
            "key": "deliverable",
            "label": "Deliverable"
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "month_phase",
        "highlightColumns": [
          "goal",
          "deliverable"
        ]
      },
      "children": []
    }
  }
}
